using System.Linq;
using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Recovery;

internal sealed class SpectralTransposeRecoveryDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The existing finite-matrix functional calculus constructs a support projection and spectral inverse square root. The shared decoder normalization lemma is the existing proof extracted once and consumed by both the original candidate and the reference completion; it claims no independent mathematical gain. Explicit Kraus completion gives a canonical CPTP candidate even for a zero CP branch. Exact recoverability and smoothness are separate conclusions.",
        H("SpectralTransposeRecovery"),
        Blocks(new[]
        {
            "spectral_support_on_kraus",
            "spectral_decoder_normalization",
            "spectral_transpose_candidate"
        }.Select(name => Describe.Lean(
            DescribeId.Create(name.Replace('_', '-')),
            DeclarationHandle.Create("D5/S3/Quantum/Recovery/SpectralTransposeRecovery." + name),
            H(name.Replace('_', ' ')),
            StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/Quantum/barnumknill2002reversal")),
            Blocks(Paragraph(Text("The existing finite-matrix functional calculus constructs a support projection and spectral inverse square root. The shared decoder normalization lemma is the existing proof extracted once and consumed by both the original candidate and the reference completion; it claims no independent mathematical gain. Explicit Kraus completion gives a canonical CPTP candidate even for a zero CP branch. Exact recoverability and smoothness are separate conclusions."))),
            DescribeRole.Theorem)).Concat(new DocumentBlock[]
        {
            new DocumentBlock.Section(H("Actual spectral smoothness and its channel specialization"), Blocks(
                Paragraph(Text("For every real normed additive commutative group E with a real normed-space structure, every topological chart model H, every topological space B with ChartedSpace H B, every model with corners I : ModelWithCorners R E H and IsManifold I infinity B, and every n,r in N, let Q : B -> Matrix (Fin n) (Fin n) C be ContMDiff I of order infinity into the real matrix self-model. Assume exactly that Q(x) is positive semidefinite and rank(Q(x)) = r for every x. Define P(x) = spectralSupport(Q(x)), W(x) = spectralInverseSqrt(Q(x)), and Z(x) = CFC.sqrt(Q(x)), using the existing functions in this owner. On the nonnegative spectrum, P uses t -> 0 if t=0 and 1 otherwise, W uses t -> (Real.sqrt(t))^(-1), with inverse zero at t=0, and Z is the nonnegative square root. These are the actual functional-calculus functions, not freely chosen projections, whitening matrices or smooth representatives. Under these hypotheses all three maps P, W and Z are ContMDiff I of order infinity into the same matrix self-model.")),
                Paragraph(Text("The local selected-column argument below uses exact_original_local_gram_certificate from Geometry/ProjectionRange/LocalGramCertificate and euclidean_range_eq_of_span_eq, smooth_mul, smooth_adj and smooth_inv from Geometry/ProjectionRange/Prebundle. For each x it supplies fixed column indices J and an open neighborhood U on which C(y)(i,j)=Q(y)(i,J(j)), G(y)=C(y)†C(y) is invertible, and range(C(y))=range(Q(y)). Thus C(y)G(y)^(-1)C(y)† is Hermitian and idempotent with the same Euclidean range as P(y); uniqueness of the orthogonal projection identifies it with the actual P(y). This establishes the local Gram formula without assuming smoothness of P. The positive-root ingredient is the square/Jordan inverse-function binding explained below and in Geometry/AlphaGeometry/HermitianCubeDerivative; it is an application of those existing declarations and the pinned CFC and local-inverse identities.")),
                Paragraph(Text("For any positive semidefinite Q, write P=spectralSupport(Q) and A=Q+I-P. Spectral functional calculus gives A positive definite, spectralInverseSqrt(Q)=P(CFC.sqrt(A))^(-1), and CFC.sqrt(Q)=P CFC.sqrt(A). On an eigenvalue t>0 the values of A, P, W and Z are respectively t, 1, 1/sqrt(t) and sqrt(t); on t=0 they are 1, 0, 0 and 0. Hence smooth Q and the Gram formula give smooth A, positive-definite square-root smoothness gives smooth CFC.sqrt(A), and smooth inversion on units and multiplication give both W and Z. These formulas hold pointwise without a rank hypothesis; constant rank enters the smooth support argument.")),
                Paragraph(Text("Neither E nor B is required to be finite-dimensional or compact by this matrix-family statement. No positive n or r, nonempty base, chosen recovery, uniform spectral gap, smooth eigenbasis or assumed smooth spectral output is required. If B is empty the conclusions are vacuous. If n=0 the unique empty matrices and their inverses in the zero-dimensional matrix algebra obey the same formulas. If r=0 then Q=P=W=Z=0 and A=I; at full rank P=I and A=Q. Repeated positive eigenvalues are harmless because the Jordan coefficients are sums of positive eigenvalues. At a rank change this smoothness conclusion need not hold: for the scalar family Q(t)=t^2, the support jumps at zero, the zero-on-kernel inverse root is unbounded near zero, and sqrt(Q(t))=abs(t) is not differentiable there. The following channel application specializes this same matrix-family derivation; its additional channel hypotheses retain their original scope.")),

                Paragraph(Text("Let B be a possibly empty compact smooth real manifold, with a model with corners I on an arbitrary finite-dimensional real normed space E and its chart model H. Let d and n be positive natural numbers, let k be a natural number, and let N_x: M_d(C) → M_n(C) be a smooth family of the canonical FiniteStateChannel.QuantumChannel maps. Here smooth means ContMDiff of order infinity after restricting each channel's linear map to R and regarding it as a continuous linear map between CStarMatrix spaces. Suppose that for every x there exists a CPTP map R_x with R_x(N_x(X)) = X for every complex d-by-d matrix X, and that rank(Q_x) = k d for Q_x = N_x(I_d). The recovery maps are pointwise witnesses; no smooth choice of R_x is assumed.")),
                Paragraph(Text("Under these hypotheses, the actual canonical maps P_x = spectralSupport(Q_x) and W_x = spectralInverseSqrt(Q_x) are globally smooth as matrix-valued maps on B. The parameter correspondence is the input index Fin d, output index Fin n, real manifold model I, and local column index Fin r with r = rank(Q_x) = k d. The CStarMatrix.ofMatrix equivalence identifies the channel value N_x(I_d) with Q_x in Matrix (Fin n) (Fin n) C. For positive semidefinite Q, spectralSupport is the orthogonal projection onto range(Q), obtained from the scalar function that is zero at zero and one elsewhere. spectralInverseSqrt applies the scalar function t ↦ (sqrt(t))⁻¹; it is zero on ker(Q) and equals Q⁻¹/² on range(Q).")),
                Paragraph(Text("Evaluation of the smooth continuous-linear-map family N at the fixed identity is smooth, and the fixed real continuous linear matrix equivalence preserves smoothness. Thus Q is smooth. Complete positivity of the actual FiniteStateChannel channel sends the positive identity to a positive element; transport through CStarMatrix.ofMatrixStarAlgEquiv and Matrix.nonneg_iff_posSemidef gives positive semidefiniteness of Q_x. These are derived properties of N, rather than additional assumptions on a replacement matrix family. Constant rank k d supplies the locally constant rank needed below.")),
                Paragraph(Text("Fix x in B and choose r linearly independent actual columns of Q_x spanning its range. Keep their indices J: Fin r → Fin n fixed, and write C_y(i,j) = Q_y(i,J(j)). The Gram matrix G_x = C_x† C_x is positive definite and invertible. Continuity of its determinant keeps G_y invertible on an open neighborhood of x. Intersect this neighborhood with one on which rank(Q_y) = r. On this same neighborhood the selected columns remain independent, lie in range(Q_y), and span it because both dimensions are r. Consequently P_y = C_y (C_y† C_y)⁻¹ C_y† there. Indeed this expression is the self-adjoint projection onto range(C_y) = range(Q_y), hence the canonical spectral support. The existing spectral_support_on_kraus identity gives the compatible support action on PSD factors and their column images; the local columns here come from Q itself and require no smooth Kraus choice.")),
                Paragraph(Text("Column selection, matrix multiplication and the adjoint are smooth over R, and matrix inversion is smooth on the open set of units. For the latter, the fixed CStarMatrix equivalence transports the existing contDiffAt_ringInverse result to the ordinary matrix inverse near an invertible matrix. Therefore the local Gram formula proves smoothness of the actual P at x. Since every x admits such a neighborhood, P is globally smooth.")),
                Paragraph(Text("Set A_x = Q_x + I_n - P_x. The PSD spectral decomposition shows that A_x acts by each positive eigenvalue of Q_x on its range and by one on its kernel. Thus A_x is positive definite; since Q and P are smooth, so is A. The positive square root is taken in the real vector space of Hermitian matrices, namely selfAdjoint.submodule R (Matrix (Fin n) (Fin n) C). The real continuous linear self-adjoint-part map gives a smooth lift of A to this subspace, with the same matrix value.")),
                Paragraph(Text("To see the square root's regularity, fix a positive definite Hermitian A and put Y = sqrt(A). The existing HermitianCubeDerivative.square_hasFDerivAt and square_contDiff give smoothness of the square map and its derivative V ↦ YV + VY. HermitianCubeDerivative.Traces.jordan_conjugation and diagonal_conjugated_jordan express this derivative in real Hermitian coordinates with coefficients lambda_i + lambda_j. All these coefficients are positive because Y is positive definite, so the derivative is injective and, in finite dimension, a continuous linear equivalence. The pinned Mathlib inverse function theorem applies. On the open positive definite neighborhood of Y, CFC.sqrt_sq identifies the actual square root as a left inverse of the square map, while CFC.sq_sqrt gives Y² = A. HasStrictFDerivAt.localInverse_unique identifies this root with the local inverse, and ContDiffAt.to_localInverse gives its smoothness. The eigenbasis is used at this fixed point only; the argument assumes neither a smooth eigenbasis nor prior continuity of the root, and asserts no ambient complex square-root regularity.")),
                Paragraph(Text("Since sqrt(A_x) is positive definite, inversion on units and smooth matrix multiplication now give smoothness of P_x (sqrt(A_x))⁻¹. On a positive eigenvalue t of Q_x this product has value 1/sqrt(t); on the zero eigenspace it has value zero. Finite spectral functional calculus therefore identifies it with the actual W_x = spectralInverseSqrt(Q_x). Equivalently W_x = P_x sqrt(A_x⁻¹). Local choices of columns and local inverses agree on overlaps because they equal these same canonical P and W. Their smoothness glues on B without a global smooth frame or a global eigenbasis.")),
                Paragraph(Text("The empty manifold is included, since smoothness is local at each point. The local Gram argument also permits r = 0: Fin 0 gives the empty Gram matrix, invertible in the zero-dimensional matrix algebra. For a rank-zero PSD family Q = 0 one has P = W = 0 and A = I; in the original positive-dimensional CPTP setting on a nonempty B, trace(Q_x) = d > 0 excludes this case. At full rank P = I and A = Q. Repeated positive eigenvalues cause no singularity, since the Jordan coefficients are sums of positive eigenvalues.")),
                Paragraph(Text("The hypotheses doing the work for P and W are smoothness of the actual Q, its positive semidefiniteness, finite matrix size and locally constant rank. Compactness and pointwise exact recoverability remain part of the original channel setting but are unused in this P/W derivation; no uniform spectral gap or chosen recovery family is needed for this conclusion. A change of rank falls outside the argument. The transpose/Petz candidate above retains its Barnum–Knill attribution. Its CPTP normalization does not establish that this candidate is an exact left inverse. The Choi construction in ST37.2 is developed in the application below. The remaining original claims concerning pi, the decoder, F, Theta and sigma and the Chern obstruction in ST38 are separate obligations; P/W smoothness alone does not establish global bundle recovery or close those claims."))
            )),
            new DocumentBlock.Section(H("Actual input-first Choi matrix and hypotheses"), Blocks(
                Paragraph(Text("Retain the full manifold and channel hypotheses of the preceding P/W application: B is a possibly empty compact smooth real manifold with model with corners I on an arbitrary finite-dimensional real normed space E and chart model H; d,n > 0 and k is a natural number. The family N_x: M_d(C) → M_n(C) consists of FiniteStateChannel.QuantumChannel maps. Its complex linear map, restricted to R and viewed as a continuous linear map between CStarMatrix spaces, is ContMDiff I of order infinity. At every x there exists a CPTP recovery R_x satisfying R_x(N_x(X)) = X for every logical matrix X, and rank(Q_x) = k d, where Q_x = N_x(I_d). There is no assumption of a smooth recovery choice. For ordinary matrices, N_x(X) means CStarMatrix.ofMatrix.symm applied to the channel on CStarMatrix.ofMatrix X; this is the same action, identity and rank used above.")),
                Paragraph(Text("Choose once, independently of x, an equivalence e: Fin(d*n) ≃ Fin d × Fin n. Use input-first vectorization vec(E)(i,alpha) = E(alpha,i), and define the unnormalized actual Choi matrix J_x((i,alpha),(j,beta)) = N_x(e_ij)(alpha,beta), with e_ij = Matrix.single i j 1. Thus trace(J_x) = d, not one. The selected Physlib MatrixMap.choi_matrix convention is output-first: its entry at ((alpha,i),(beta,j)) is this same entry. The fixed coordinate swap, with no transpose or complex conjugation of N, relates the two conventions. Put P_x = spectralSupport(Q_x) and W_x = spectralInverseSqrt(Q_x), exactly as in the preceding application. All formulas below use this one J, Q, P, W and this fixed equivalence e.")),
                Paragraph(Text("The application gives sqrt(J_x) = d^(-1/2) (I_d tensor W_x) J_x, rank(J_x) = k, and a globally smooth prescribed family of d*n Kraus matrices and its packed Hilbert isometry. The root formula is pointwise and uses exact recovery but no rank hypothesis. The rank conclusion uses rank(Q_x) = k d separately. Smoothness uses the already established smooth P/W application together with hN; the fixed-column action and isometry identities themselves hold for every finite-dimensional CPTP channel, even without recovery."))
            )),
            new DocumentBlock.Section(H("Deriving the positive root from the actual channel"), Blocks(
                Paragraph(Text("Fix x and suppress it. Apply the existing krausRepresentation to N and to an actual recovery R. This gives finite rectangular Kraus families E_a: C^d → C^n and R_t: C^n → C^d with their all-matrix action equations. The canonical families may be indexed by a in Fin n × Fin d and t in Fin d × Fin n; no family is chosen smoothly in x. Trace preservation implies sum_a E_a† E_a = I_d and sum_t R_t† R_t = I_n: cyclicity gives trace(X sum K†K) = trace(X) for every X, and testing X=e_ji extracts each (i,j) entry.")),
                Paragraph(Text("The composite family R_t E_a represents the identity on every d-by-d matrix. The existing identity_kraus_scalar and left_inverse_error_products results therefore apply to these actual families. Choose i0 in Fin d, possible since d>0, and put D(t,a) = (R_t E_a)(i0,i0) and c = D†D. Then E_a† E_b = c(a,b) I_d. In detail, R_t E_a = D(t,a) I_d and recovery TP give E_a† E_b = sum_t (R_t E_a)†(R_t E_b) = sum_t conjugate(D(t,a)) D(t,b) I_d. Hence c is positive semidefinite and Hermitian; the (i0,i0) entry of channel TP gives trace(c)=1. These are consequences of the actual CPTP left inverse, not extra scalar-error-product premises.")),
                Paragraph(Text("Form two rectangular rearrangements of the actual E entries: T((i,alpha),a)=E_a(alpha,i), and H(alpha,(a,i))=E_a(alpha,i). The Choi-of-Kraus formula, after the fixed output/input swap, gives J=TT†. Summing diagonal entries of E_a† E_b=c(a,b)I_d gives T†T=d c. Evaluating the actual channel at I_d gives Q=sum_a E_a E_a†=HH†, while entrywise scalarity gives H†H=c tensor I_d. These identities also prove J and Q positive semidefinite by the Gram-matrix positivity suppliers.")),
                Paragraph(Text("Set L=I_d tensor Q. For each b, Q E_b=sum_a E_a(E_a† E_b)=sum_a c(a,b)E_a, so LT=Tc by vectorization. Both L and c are Hermitian; taking adjoints gives T†L=cT†. Consequently LJ=TcT†=JL, and J²=T(T†T)T†=d TcT†=d LJ. This derivation establishes both the polynomial relation and the commutation needed for normalization from the actual channel, rather than postulating them from the desired root formula.")),
                Paragraph(Text("The existing spectral_decoder_normalization applied to the same E gives W†=W, P†=P, P²=P and sum_a (E_a†W)†(E_a†W)=P. Expanding the last equality using Q=sum_a E_a E_a† yields WQW=P. Independently, spectral_support_on_kraus gives PE_a=E_a for every a. With S=I_d tensor P and M=I_d tensor W, these are ST=T and SJ=J, and MLM=S. The scalar function t ↦ (sqrt(t))⁻¹ is zero at zero and nonnegative on the finite spectrum of Q, so cfc_nonneg proves W positive semidefinite, and Matrix.PosSemidef.kronecker proves M positive semidefinite. J is positive semidefinite because J=TT†. Thus all support and positivity premises refer to the actual spectral functions already defined above.")),
                Paragraph(Text("To obtain the remaining commutations, inspect the (i,j) block of LJ=JL: Q commutes with N(e_ij). Commute.cfc_real then implies W N(e_ij)=N(e_ij)W for every i,j, hence MJ=JM. Applying the same functional-calculus commutation to Q itself gives WQ=QW and therefore ML=LM. Although inverse square root is not continuous at zero on the whole real line, its restriction to the finite spectrum is continuous; this pointwise CFC argument does not assume ambient regularity at zero or a spectral gap uniform in x.")),
                Paragraph(Text("Let r=1/sqrt(d)>0 and Y=r MJ. The existing commuting-positive-product theorem Commute.mul_nonneg, applied to M and J and their just-proved commutation, gives MJ positive semidefinite; positive real scaling gives Y positive semidefinite. Since r²d=1, the actual identities above yield Y²=r² M² J²=r²d M²LJ=(MLM)J=SJ=J. CFC.sqrt_unique now identifies Y with the actual positive square root of J. Every premise of this use of uniqueness has been discharged: the square identity uses the Gram relation, the spectral normalization and the support action, and positivity uses the actual commutation. No rank relation was used.")),
                Paragraph(Text("The same support action also locates the actual Choi support: S spectralSupport(J)=spectralSupport(J). Indeed SJ=J, and finite spectral calculus writes spectralSupport(J)=J cfc(t ↦ t⁻¹,J), with zero retained at t=0; multiplication gives the claimed absorption. This is an inclusion of ranges, not a global smooth basis of either range."))
            )),
            new DocumentBlock.Section(H("The separate rank calculation"), Blocks(
                Paragraph(Text("For any complex rectangular matrix, the ranks of F, FF† and F†F agree. Applying Matrix.rank_self_mul_conjTranspose and Matrix.rank_conjTranspose_mul_self to T gives rank(J)=rank(d c)=rank(c), since d>0. Applying the same facts to H gives rank(Q)=rank(c tensor I_d). At this fixed point choose a unitary spectral diagonalization c=U diag(lambda_a) U†. Conjugation by U tensor I_d is invertible and preserves rank; the resulting diagonal entries are lambda_a, each repeated d times. Matrix.rank_diagonal counts precisely the nonzero entries, so rank(c tensor I_d)=d rank(c). Zero eigenvalues contribute zero, and repeated positive eigenvalues contribute with their full multiplicity. Hence rank(Q)=d rank(J), and the original rank(Q)=k d hypothesis implies rank(J)=k by cancellation of positive d. This argument needs no k>0 premise and no smoothly varying eigenvectors."))
            )),
            new DocumentBlock.Section(H("Every prescribed column and the redundant dilation"), Blocks(
                Paragraph(Text("Write Z_x=CFC.sqrt(J_x). For every mu in Fin(d*n), including any column that is zero, define A_mu(x)(alpha,i)=Z_x((i,alpha),e(mu)). This is literal inverse vectorization of the mu-labelled column of the actual positive root, not selection of k nonzero columns. Pack the same entries as V_x((alpha,mu),i)=A_mu(x)(alpha,i), in output × environment order. Thus V_x has n*(d*n) rows and d columns; its environment is C^(d*n), regardless of the rank k of J. The fixed equivalence e labels Choi columns; it does not identify or quotient a moving support space.")),
                Paragraph(Text("Because J is positive semidefinite, CFC.sqrt_nonneg and CFC.sqrt_mul_sqrt_self give Z†=Z and ZZ†=J. Summing over all mu via the bijection e therefore gives sum_mu A_mu(alpha,i) conjugate(A_mu(beta,j))=J((i,alpha),(j,beta))=N(e_ij)(alpha,beta). By linearity on matrix units, equivalently by the existing choi_of_kraus and choi_matrix_inj after the coordinate swap, N(X)=sum_mu A_mu X A_mu† for every complex d-by-d matrix X. This includes off-diagonal and nonpositive matrices, not only density operators. Testing the actual TP law on e_ji as above gives sum_mu A_mu† A_mu=I_d.")),
                Paragraph(Text("The (i,j) entry of V†V is sum_(alpha,mu) conjugate(A_mu(alpha,i)) A_mu(alpha,j), which is the (i,j) entry of sum_mu A_mu† A_mu. Thus V†V=I_d. For u,v in EuclideanSpace C (Fin d), expansion gives inner(Vu,Vv)=inner(u,V†Vv)=inner(u,v), so Matrix.toEuclideanLin V defines a complex linear Hilbert isometry into EuclideanSpace C (Fin n × Fin(d*n)). The norm is the Euclidean/Hilbert norm, not the supremum norm of a raw Pi type.")),
                Paragraph(Text("For every logical matrix X and output coordinates alpha,beta, sum_mu (VXV†)((alpha,mu),(beta,mu))=sum_mu (A_mu X A_mu†)(alpha,beta)=N(X)(alpha,beta). This is the coordinate partial trace over the environment in the stated output × environment packing. More generally, let rRef be any reference index type and X a coordinate matrix on rRef × Fin d. For every rho,sigma in rRef, define X_(rho,sigma)(i,j)=X((rho,i),(sigma,j)). Then sum_mu sum_j sum_i A_mu(alpha,i) X((rho,i),(sigma,j)) conjugate(A_mu(beta,j))=N(X_(rho,sigma))(alpha,beta). The identity holds block by block with no sum over reference coordinates. For a finite reference space it is exactly the partial-trace equality for (I_ref tensor V) X (I_ref tensor V)† and (id_ref tensor N)(X); for an arbitrary index type it asserts this coordinate-block identity, not an unproved infinite-dimensional operator or convergence theorem."))
            )),
            new DocumentBlock.Section(H("Global smooth transport and its boundary"), Blocks(
                Paragraph(Text("Return to the full manifold family. The preceding P/W application already proves that x ↦ W_x is globally ContMDiff of order infinity from the actual smooth Q_x and its constant rank. Use that result directly; the positive-root regularity argument is already documented there and in the existing HermitianCubeDerivative exposition. For every fixed i,j, evaluating hN at CStarMatrix.ofMatrix(e_ij) is smooth by ContMDiff.clm_apply, and the real restriction of CStarMatrix.ofMatrixL.symm transports it to the ordinary entries of N_x(e_ij). The root formula now reads Z_x((i,alpha),(j,beta))=d^(-1/2) sum_gamma W_x(alpha,gamma) N_x(e_ij)(gamma,beta). Its entries are finite sums of products of smooth functions, so contMDiff_pi_space and contMDiffAt_finsetSum give global smoothness of the actual Z. Fixed entry selection through e gives global smoothness of x ↦ (A_mu(x))_mu and of the packed matrix x ↦ V_x. This proves smooth transport into fixed ambient matrix and Hilbert spaces; the pointwise Kraus families and recoveries used in the algebra disappear from the formula.")),
                Paragraph(Text("All d*n columns remain in these globally defined maps, including actual zero columns and every column at repeated eigenvalues. Rank(J)=k does not mean that only k of these prescribed coordinate columns are nonzero; reducing to k Kraus operators would require an additional choice and is not part of this construction. No smooth rank-k frame, truncation, eigenbasis, recovery choice, or global trivialization of the Choi support bundle is supplied. Local choices in the P/W proof agree because they equal the same canonical P and W, and the root formula equals the unique canonical sqrt(J), so its global use requires no choices on overlaps.")),
                Paragraph(Text("If B is empty, the pointwise hypotheses and all smoothness and rank conclusions are vacuous, including k=0. On nonempty B with the original d>0 CPTP assumptions, trace(Q_x)=d>0, hence rank(Q_x)>0 and k=0 is impossible. The algebraic zero PSD case has P=W=J=Z=0 and all prescribed columns zero; a zero channel on a positive-dimensional logical space is not TP and cannot satisfy the isometry conclusion. No such impossible input is added to the original theorem. Kernels of nonzero Q and J, zero eigenvalues, and repeated positive eigenvalues are fully allowed; the constant-rank hypothesis is needed for the stated smoothness argument, whereas the fixed-column action and dilation formulas are pointwise.")),
                Paragraph(Text("The map V_x is a mathematical redundant-environment dilation of the actual N_x. It does not assert physical access to that environment, a realizable reset, a smooth family of unitary extensions, or an implementation of an exact decoder. The remaining original obligations concerning pi, the decoder, F, Theta and sigma, their global bundle transport, and the Chern obstruction in ST38 remain separate. The construction and its smoothness do not close those obligations or the parent recovery problem."))
            )),
            new DocumentBlock.Section(H("Existing source identities for this application"), Blocks(
                Paragraph(Text("The D5 suppliers used here are the existing FiniteKrausChannel.krausRepresentation and its selected PhyslibLeaf.MatrixMap.choi_matrix, choi_of_kraus and choi_matrix_inj in D5/S3/Quantum/Foundation/FiniteKrausRepresentation.lean; KrausLeftInverseNecessity.identity_kraus_scalar and left_inverse_error_products in D5/S3/Quantum/Recovery/KrausLeftInverseNecessity.lean; and SpectralTransposeRecovery.spectral_support_on_kraus and spectral_decoder_normalization in this owner. Immutable repository revision 8285cb18252b3e66a8f562c41ea3190dc956161d identifies these sources. Their SHA-256 identities, respectively, are 126a35f76d64c054b36e984eae127ad05843e40bebea1e1076572995baecd67a, c2b40017a649e314cf886ae669108e12cc71e62f3b9abc36b01aebb20bb19113 and a25dd8b3615e5b30c5b5c9bd2f78f703b850e4b4834450e67c760e0098058ecd. The selected Kraus/Choi source retains Alex Meiburg's attribution and its Physlib revision 6a09b2d1761a0d4430083045a247eb121d8da260; the transpose/Petz candidate retains its existing Barnum–Knill attribution.")),
                Paragraph(Text("At Mathlib revision db584cd6d46c92f209a44c0f1c829460d327499d, the functional-calculus steps use Commute.cfc_real in Mathlib/Analysis/CStarAlgebra/ContinuousFunctionalCalculus/Commute.lean, CFC.sqrt_unique, sqrt_nonneg and sqrt_mul_sqrt_self in Mathlib/Analysis/SpecialFunctions/ContinuousFunctionalCalculus/Rpow/Basic.lean, and cfc_nonneg with the matrix order and Kronecker positivity APIs. The rank identities and diagonal count are in Mathlib/LinearAlgebra/Matrix/Rank.lean. The smooth evaluation and coordinate assembly use ContMDiff.clm_apply, contMDiff_pi_space and contMDiffAt_finsetSum in the manifold API, with the CStarMatrix equivalences in Mathlib/Analysis/CStarAlgebra/CStarMatrix.lean. The P/W application above supplies smooth W; its positive-definite-root ingredient uses the existing HermitianCubeDerivative.square_hasFDerivAt, square_contDiff and Traces coordinate identities at the same repository revision. These source identities and the ordinary argument specify an application of existing results; this exposition introduces no new canonical Lean declaration or independent novelty claim."))
            ))
        }).ToArray())));
}
